<template>
	<div class="flex min-h-dvh flex-col bg-ui-surface-gray-50 pb-safe">
		<div
			ref="headerRef"
			class="sticky top-0 z-30 border-b border-ui-line-gray-200 bg-ui-surface px-5 py-4"
			style="padding-top: calc(1rem + env(safe-area-inset-top))"
		>
			<div class="flex items-center gap-2">
				<button
					type="button"
					class="-ml-1 flex h-10 w-10 shrink-0 items-center justify-center rounded-md text-ui-action transition-colors hover:bg-ui-surface-blue-50 active:bg-ui-surface-blue-100"
					aria-label="Kembali"
					@click="goBack"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-7 w-7"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="m12 19-7-7 7-7" />
						<path d="M19 12H5" />
					</svg>
				</button>
				<h1 class="flex-1 truncate text-xl font-semibold text-ui-ink-gray-900">
					Pengaturan HR
				</h1>

				<!-- Edit (ikon) — sama dengan Data Pengajuan. Save ada di bar bawah. -->
				<div class="shrink-0">
					<button
						v-if="formRef && !formRef.editMode && formRef.canEditDoc"
						type="button"
						class="flex h-10 w-10 items-center justify-center rounded-lg border border-ui-line-gray-300 bg-ui-surface text-ui-ink-gray-700 transition hover:bg-ui-surface-gray-50 active:bg-ui-surface-gray-100"
						aria-label="Edit"
						title="Edit"
						@click="formRef.enterEditMode()"
					>
						<svg
							xmlns="http://www.w3.org/2000/svg"
							viewBox="0 0 24 24"
							class="h-5 w-5"
							fill="none"
							stroke="currentColor"
							stroke-width="2"
							stroke-linecap="round"
							stroke-linejoin="round"
						>
							<path d="M12 20h9" />
							<path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4 12.5-12.5z" />
						</svg>
					</button>
				</div>
			</div>
		</div>

		<!-- Doctype Single: nama dokumennya sama dengan nama doctype. Field yang
		     boleh diubah mengikuti izin tulis (HR Manager/System Manager); HR User
		     hanya melihat. -->
		<MetaDocForm
			ref="formRef"
			:doctype="DOCTYPE"
			:name="DOCTYPE"
			:sticky-top="tabTop"
			class="flex-1"
		/>
	</div>
</template>

<script setup>
import { nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import MetaDocForm from '../components/MetaDocForm.vue'

const DOCTYPE = 'Pengaturan HR'
const router = useRouter()
const formRef = ref(null)

function goBack() {
	if (window.history.length > 1) router.back()
	else router.push({ name: 'Home' })
}

const headerRef = ref(null)
const tabTop = ref(0)
function ukur() {
	tabTop.value = Math.max(0, (headerRef.value?.offsetHeight || 0) - 1)
}
let ro = null
onMounted(() => {
	nextTick(ukur)
	if (typeof ResizeObserver !== 'undefined' && headerRef.value) {
		ro = new ResizeObserver(ukur)
		ro.observe(headerRef.value)
	}
})
onBeforeUnmount(() => ro?.disconnect())
</script>
